/// The card art (and the basket template) loaded from the bundle once, then kept: decoding a WebP per frame
/// would stutter the swipe. iOS decodes WebP natively from iOS 14.
enum CardArtImages {
	private static let cache = NSCache<NSString, UIImage>()

	static func image(_ name: String) -> UIImage? {
		if let hit = cache.object(forKey: name as NSString) { return hit }
		guard let path = Bundle.main.path(forResource: name, ofType: "webp"), let image = UIImage(contentsOfFile: path) else { return nil }
		cache.setObject(image, forKey: name as NSString)
		return image
	}

	/// The deck art for a ticker, or nil for a brand added since the art was last generated.
	static func forTicker(_ ticker: String) -> UIImage? { cardArt[ticker].flatMap(image) }

	/// The basket template a brand without its own art is drawn on, its logo set into the glass (GlassLogo).
	static var basketTemplate: UIImage? { image("disc_basket_template") }
}
